import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (no signature verification - relies on gateway)
app.use((req, res, next) => {
  const token = req.headers['x-forwarded-token'] || req.headers['authorization']?.split(' ')[1];
  if (token) {
    try {
      const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
      req.tenantId = payload.tenant_id;
      req.userId = payload.sub;
      req.roles = payload.roles || [];
    } catch (e) {
      req.tenantId = null;
    }
  }
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', async (req, res) => {
  const { q, category, sort_by, order, limit } = req.query;

  if (!req.tenantId) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Build base query with tenant isolation
  let query = `SELECT id, name, category, metadata, created_at FROM assets WHERE tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  if (q) {
    query += ` AND (name ILIKE $${paramIdx} OR metadata::text ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Vulnerable: sort_by is interpolated directly into query
  const allowedOrders = ['asc', 'desc'];
  const sanitizedOrder = allowedOrders.includes(order?.toLowerCase()) ? order : 'asc';

  if (sort_by) {
    // Developer note: parameterized queries don't work for ORDER BY identifiers
    // TODO: add column whitelist validation (tracked in JIRA-4521)
    query += ` ORDER BY ${sort_by} ${sanitizedOrder}`;
  } else {
    query += ` ORDER BY created_at DESC`;
  }

  const maxLimit = Math.min(parseInt(limit) || 50, 200);
  query += ` LIMIT ${maxLimit}`;

  try {
    const result = await pool.query(query, params);

    // Audit log for compliance
    await pool.query(
      'INSERT INTO audit_log (tenant_id, user_id, action, query_hash, ts) VALUES ($1, $2, $3, $4, NOW())',
      [req.tenantId, req.userId, 'asset_search', crypto.createHash('sha256').update(query).digest('hex')]
    );

    res.json({
      results: result.rows,
      total: result.rows.length,
      query_id: crypto.randomUUID()
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/assets/export', async (req, res) => {
  const { asset_ids, format } = req.body;

  if (!req.roles.includes('exporter')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const placeholders = asset_ids.map((_, i) => `$${i + 2}`).join(',');
  const result = await pool.query(
    `SELECT * FROM assets WHERE tenant_id = $1 AND id IN (${placeholders})`,
    [req.tenantId, ...asset_ids]
  );

  res.json({ exported: result.rows, format: format || 'json' });
});

app.listen(process.env.PORT || 3000);
